Domain-Driven Design (DDD).ejemplo:
// Aggregate Root protegiendo invariante de negocio
class Orden {
  agregarItem(sku: Sku, qty: Cantidad) {
    if (this.estado !== 'BORRADOR') throw new Error('Orden cerrada');
    this.items.push(new LineaOrden(sku, qty));
    this.registrarEvento(new ItemAgregado(this.id, sku));
  }
}

Patrón Adapter (GoF).ejemplo:
interface PasarelaPago { cobrar(centavos: number): Promise<void>; }
class StripeAdapter implements PasarelaPago {
  constructor(private stripe: StripeSDK) {}
  async cobrar(centavos: number) {
    await this.stripe.charges.create({ amount: centavos, currency: 'usd' });
  }
}

Patrón Decorator (GoF).ejemplo:
interface Notificador { enviar(msg: string): void; }
class ConLog implements Notificador {
  constructor(private inner: Notificador) {}
  enviar(msg: string) {
    console.log('Enviando:', msg);
    this.inner.enviar(msg);
  }
}

Patrón Factory Method (GoF).ejemplo:
abstract class Exportador {
  abstract crearFormato(): Formato; // Factory Method
  exportar(datos: string) {
    const fmt = this.crearFormato();
    return fmt.render(datos);
  }
}
class ExportadorPDF extends Exportador {
  crearFormato() { return new FormatoPDF(); }
}

Patrón Observer (GoF).ejemplo:
class Cuenta {
  private obs: ((saldo: number) => void)[] = [];
  suscribir(fn: (s: number) => void) { this.obs.push(fn); }
  depositar(monto: number) {
    this.saldo += monto;
    this.obs.forEach(fn => fn(this.saldo));
  }
}

Patrón Singleton (GoF).ejemplo:
class Config {
  private static instance: Config;
  private constructor(readonly env: string) {}
  static getInstance(): Config {
    if (!Config.instance) Config.instance = new Config(process.env.NODE_ENV ?? 'dev');
    return Config.instance;
  }
}

Patrón Strategy (GoF).ejemplo:
type PoliticaDescuento = (total: number) => number;
const descuentos: Record<string, PoliticaDescuento> = {
  VIP: (t) => t * 0.8,
  BLACK_FRIDAY: (t) => t * 0.7,
  NORMAL: (t) => t,
};
const cobrar = (total: number, tipo: string) => descuentos[tipo](total);
